// TH14 v1.00b Extra, Boss8 non-spell #8.
// Source: st07bs.ecl.txt:795-847 (entry), Boss8_at st07bs.ecl.txt:849-879, rank4 (!O only).
// card frame = source t + 120: the Boss8 entry (timerReset) maps to card frame 120,
// its 60+80 prelude is inside the source 3000-frame limit; +300 tail frames after it.

const TIME_LIMIT: int = 3424;      // 120 opening buffer + 3000 source limit + 300 tail + 4 startup
const OPENING_BUFFER: int = 120;

// Source floats converted to BAM (1 rad = 65536 / 2pi).
const SWEEP_BAM: int = 40503;      // %B = 3.883222 rad
const LAYER_BAM: int = 728;        // etAngle spread 0.06981317 rad
const PRELUDE_A: int = 60;         // st07bs.ecl.txt:832
const PRELUDE_B: int = 80;         // st07bs.ecl.txt:838

sub main() {
    _ = spawn_enemy(0fx, 0fx, 13500, 0, 0, 0, control);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // source slot0 interrupt: hp threshold 3500, time 3000 (st07bs.ecl.txt:828)
    phase_begin(0, entrance, TIME_LIMIT, 3500);
    wait_spell();
    loop { wait(1); }
}

async sub entrance() {
    wait(OPENING_BUFFER);
    // source Boss common start position (st07bs.ecl.txt:17); Boss8 lifeSet 13500 (805)
    _ = spawn_enemy(0fx, 128fx, 13500, 0, 0, 0, boss_main);
    loop { wait(1); }
}

async sub boss_main() {
    set_invuln(65535);
    // Boss context boxes 48x48 -> circle radius 24 (TH16/TH18 shared box rule)
    set_hitbox(24fx);
    set_hurtbox(24fx);
    wait(PRELUDE_A);   // 832
    wait(PRELUDE_B);   // 838 (833-837: moveLimit handled by the move helper; ANM/sound omitted)
    spawn boss8_at();  // 839
    spawn boss8_move();// 840 -> Boss8_1364
    loop { wait(1); }
}

// Boss8_at (st07bs.ecl.txt:849-879): mode10 fixed alternating-layer ring,
// N=6 ways x M=9 layers, speeds 3.0..2.2, every 13 frames.
async sub boss8_at() {
    var a: int = rand(65536) - 32768;  // %A = %RANDRAD sampled once at configuration
    var b: int = SWEEP_BAM;            // %B
    // source t=140 first volley, 13-frame period; the 3000-frame interrupt stops
    // the async, so the last volley is the one before t=3000 (220 volleys).
    for burst in 0..220 {
        for q in 0..9 {
            var h: int = ((q + 1) / 2) * LAYER_BAM;  // H(M,q), M odd
            var k: int = ((q + 1) / 2) * 2;          // paired layer speed index
            var speed: fx = 3fx + (2.2fx - 3fx) * (k as fx) / 8fx;
            // etDist 16 along the bullet angle, ANIM entry shifts back 4*initial speed
            var dist: fx = 16fx - 4fx * speed;
            for i in 0..6 {
                var rot: int = (i * 65536) / 6 + h;
                var dir: int = a + rot;
                if q % 2 != 0 { dir = a - rot; }
                var ang: angle = dir as angle;
                // etOffset (0,24) from the boss; ANIM spawn stage otherwise omitted
                var sx: fx = $self_x + dist * cos(ang);
                var sy: fx = $self_y + 24fx + dist * sin(ang);
                _ = fire(TH14_RICE, 8, sx, sy, speed, ang, none, none);
            }
        }
        a = a + b;
        if burst % 8 == 7 { b = -b; }
        wait(13);
    }
}

// Boss8_1364/1412 (st07bs.ecl.txt:841-845): wait(120) -> moveRand(60,4,1.0f).
// moveLimit(0,128,280,64): clamp x in [-140,140], y in [96,160].
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_move(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand() {
    // moveRand direction choice; inner band is center +/- width/4 and height/4.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var pick: int = rand(65536) % 3;
        if $player_x > $self_x {
            if pick == 0 { a = a + 32768; }
        } else {
            if pick != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native guard around +/- pi/2 with 0.05 rad epsilon
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_move(a as angle);
}

async sub boss8_move() {
    wait(120);
    loop {
        move_rand();
        // phase 5 runs after ECL: arm the next source movement tick each frame
        for i in 0..120 {
            wait(1);
            arm_next_step();
        }
    }
}

